"""0x82467D90: XAudio XMA source render (the ph_vt5A60 name is autogenerated).

Exact comparison, including output buffers, gain/filter history, recursive locks,
HRESULT exits, refill thresholds and callback order. DSP and hardware decoder
callees are coherent bounded models: this checks the caller's orchestration, not
XMA decoding or resampling. No memory is ignored. Callbacks mutate flags/list
links, so state must be reloaded after them. Valid layouts have <= 6 streams,
0..2 channels each, readable gain state even with no streams, and enough output.
The r13/PCR identity uses the repository's g_sda_base host representation.

Run mutation checks after the normal two-seed checks:
PYTHONPATH=tools/lift-check tools/lift-check/.venv/bin/python \
tools/lift-check/specs/xma_source_render.py
"""
import struct

from liftcheck.spec import *

FUNCTION = "XmaSource_Render"
ADDRESS = 0x82467D90
SOURCE = "src/rage/audio/xma_source.cpp"
FP_CONTRACT = "off"
TRIALS = 1000
EXTERNS = {"g_sda_base": 0x82600000}


def u32(ctx, addr):
    return int.from_bytes(ctx.read(addr, 4), "big")


def w32(ctx, addr, value):
    ctx.write(addr, struct.pack(">I", value & 0xFFFFFFFF))


def frame_get(ctx):
    buffer = ctx.r(3)
    ctx.write(ctx.r(4), ctx.read(buffer, 12))
    ctx.ret(r3=u32(ctx, buffer + 12))


def frame_resize(ctx):
    # The input descriptor is an in/out local; its channel byte is replaced.
    ctx.ret(r3=u32(ctx, ctx.r(3) + 16))


def decoder_lock(ctx):
    ctx.ret(r3=u32(ctx, ctx.r(3) + 12))


def available(ctx):
    ctx.ret(r3=u32(ctx, ctx.r(3) + 32 + ctx.r(4) * 16))


def peek(ctx):
    state = ctx.r(3) + 32 + ctx.r(4) * 16
    w32(ctx, ctx.r(5), u32(ctx, state + 4))
    ctx.ret(r3=min(u32(ctx, state), u32(ctx, state + 8)))


def process(ctx):
    stream = ctx.r(3)
    n = min(u32(ctx, stream + 4), u32(ctx, stream + 24) - u32(ctx, stream + 28),
            ctx.rng.choice([1, 31, 64, 128, 256]))
    offset = u32(ctx, stream + 28)
    output = u32(ctx, stream + 20)
    channels = ctx.read(stream + 13, 1)[0]
    # Distinct nonzero samples make zero-fill offsets/strides observable.
    for channel in range(channels):
        ctx.write(output + channel * 1024 + offset * 4, struct.pack(">f", 0.25 + channel) * n)
    w32(ctx, stream + 28, offset + n)
    ctx.ret(r3=n)


def consume(ctx):
    state = ctx.r(3) + 32 + ctx.r(4) * 16
    n = ctx.r(5)
    left = u32(ctx, state)
    assert n <= left
    w32(ctx, state, left - n)
    w32(ctx, state + 4, u32(ctx, state + 4) + n * 2)
    w32(ctx, ctx.r(6), u32(ctx, state + 4))


def samples_played(ctx):
    ctx.ret(r3=u32(ctx, ctx.r(3) + 20))


def submit(ctx):
    source = ctx.r(3)
    decoder = u32(ctx, source + 180)
    # Real submission can change the source flags while the global lock is down.
    ctx.write(source + 168, bytes([ctx.read(source + 168, 1)[0] ^ ctx.read(decoder + 24, 1)[0]]))
    ctx.ret(r3=u32(ctx, decoder + 16))


def unlock(ctx):
    ctx.ret(r3=u32(ctx, ctx.r(3) + 28))


def set_flags(ctx):
    source = ctx.r(3) - 16
    flags = ctx.read(source + 168, 1)[0]
    ctx.write(source + 168, bytes([(flags & ~ctx.r(4)) | ctx.r(5)]))


def stop(ctx):
    source = ctx.r(3)
    flags = ctx.read(source + 168, 1)[0]
    ctx.write(source + 168, bytes([(flags & ~1) | 16]))


def complete(ctx):
    source = ctx.r(3) - 16
    decoder = u32(ctx, source + 180)
    # Both locks have been returned to their entry nesting depths.
    assert u32(ctx, source + 268) == u32(ctx, decoder + 128)
    assert u32(ctx, 0x825E7874) == u32(ctx, decoder + 132)
    buffer = ctx.r(4)
    link = buffer + u32(ctx, source + 28)
    next_link, previous_link = u32(ctx, link), u32(ctx, link + 4)
    w32(ctx, previous_link, next_link)
    w32(ctx, next_link + 4, previous_link)
    ctx.write(buffer + 96, b"\x05")


CALLS = {
    "KeRaiseIrqlToDpcLevel": stub(ret=lambda ctx: ctx.rng.randrange(4), args=()),
    "KeAcquireSpinLockAtRaisedIrql": stub(ret="void", deref={"r3": 16}),
    "KeReleaseSpinLockFromRaisedIrql": stub(ret="void", deref={"r3": 16}),
    "KfLowerIrql": stub(ret="void"),
    "XmaDecoder_IsEnabled": run(),
    "XmaDecoder_Lock": model(decoder_lock),
    "XAudioFrame_Get": model(frame_get),
    "XAudioFrame_Resize": model(frame_resize, deref={"r4": 12}),
    "XmaDecoder_Wait": stub(ret="void"),
    "XmaDecoder_Available": model(available),
    "XmaDecoder_Peek": model(peek),
    "XmaRenderStream_Process": model(process, deref={"r3": 88}),
    "XmaDecoder_Consume": model(consume, deref={"r6": 4}),
    "XmaDecoder_SamplesPlayed": model(samples_played),
    "XmaSource_SubmitBuffers": model(submit),
    "XmaDecoder_Unlock": model(unlock),
    "source.vfn_11": model(stop, args=("r3", "r4")),
    "interface.vfn_17": model(set_flags, args=("r3", "r4", "r5")),
    "interface.vfn_19": model(complete, args=("r3", "r4", "r5")),
}


def inputs(t):
    rng = t.rng
    source = t.alloc(280, "source")
    decoder = t.alloc(144, "decoder", fill="zero")
    streams = t.alloc(6 * 88, "streams")
    output = t.alloc(12 * 1024, "planarOutput")
    frame = t.alloc(20, "frame")
    thread = t.alloc(16, "thread")
    count = rng.choice([0, 1, 1, 2, 3, 6])
    mode = rng.randrange(12)
    flags = rng.choice([1, 3, 5, 7, 9, 11, 13, 15, 0, 16, 17, 255])
    if mode in (0, 1, 2):
        flags = [1, 3, 5][mode]
    t.w32(source, t.vtable("source", slots=12))
    t.w32(source + 16, t.vtable("interface", slots=20))
    t.w8(source + 52, count)
    t.wf32(source + 108, rng.choice([-0.0, 0.0, 0.5, 1.0, -2.0, rng.uniform(-10, 10)]))
    t.w8(source + 168, flags)
    t.w16(source + 170, rng.choice([0, 1, 2, 3, 65535]))
    t.w32(source + 180, decoder)
    t.w32(source + 184, streams)
    t.w32(decoder + 4, 0 if mode == 3 else 0x40000)
    t.w32(decoder + 12, 0x80004005 if mode == 4 else rng.choice([0, 0, 1]))
    t.w32(decoder + 16, rng.choice([0, 1, 0x80004005]))
    t.w32(decoder + 20, t.u32())
    t.w8(decoder + 24, rng.choice([0, 0, 0, 1, 16]))
    t.w32(decoder + 28, rng.choice([0, 1, 0x80004005]))
    for i in range(6):
        channels = rng.choice([0, 1, 2])
        t.w8(source + 60 + i * 8, channels)
        t.w8(streams + i * 88 + 13, channels)
        for off in (36, 40, 48):
            t.wf32(streams + i * 88 + off, rng.uniform(-4, 4))
        t.w16(source + 250 + i * 2, rng.choice([0, 1, 127, 128, 255, 256, 512, 65535]))
        t.w32(decoder + 32 + i * 16, rng.choice([0, 1, 64, 128, 255, 256, 257, 512, 1024]))
        t.w32(decoder + 36 + i * 16, t.alloc(4096, f"decoded{i}"))
        t.w32(decoder + 40 + i * 16, rng.choice([0, 1, 31, 128, 256, 512]))
    t.w8(frame, 0)
    t.w8(frame + 1, rng.randrange(13))
    t.w32(frame + 4, 48000)
    t.w32(frame + 8, output)
    t.w32(frame + 12, 0x8007000E if mode == 5 else rng.choice([0, 1]))
    t.w32(frame + 16, 0x80004005 if mode == 6 else rng.choice([0, 1]))
    # Empty, all-completed, mixed, and multi-completed intrusive lists.
    offset = rng.choice([0, 8, 24, 64])
    t.w32(source + 28, offset)
    buffers = [t.alloc(112, f"queued{i}") for i in range(rng.randrange(5))]
    links = [source + 20] + [buffer + offset for buffer in buffers]
    for i, link in enumerate(links):
        t.w32(link, links[(i + 1) % len(links)])
        t.w32(link + 4, links[(i - 1) % len(links)])
    for buffer in buffers:
        t.w8(buffer + 96, 4 if mode in (0, 1, 2) else rng.choice([0, 1, 3, 4, 4, 5]))
    for lock, saved in [(source + 264, decoder + 128), (0x825E7870, decoder + 132)]:
        depth = rng.choice([0, 0, 1, 2, 7])
        t.w32(lock, t.u32())
        t.w32(lock + 4, depth)
        t.w32(lock + 8, thread if depth else 0)
        t.w8(lock + 12, rng.randrange(4))
        t.w32(saved, depth)
    t.w32(0x82600000, thread)
    t.args(r3=source, r4=t.u32(), r5=frame, r13=thread)


MUTATIONS = [
    ("lose earlier stream channels", "channels += self->formats[i].channels;",
     "channels = self->formats[i].channels;"),
    ("wrong underrun channel stride", "stream.output + stream.outputOffset + channel * 256",
     "stream.output + stream.outputOffset + channel * 255"),
    ("saturate the wrapping fade counter", "--self->fadeTicks;",
     "if (self->fadeTicks) --self->fadeTicks;"),
    ("miss the exact refill threshold", "available - consumed <= self->refillThreshold[i]",
     "available - consumed < self->refillThreshold[i]"),
    ("swallow a decoder error", "return result;", "return 0;"),
    ("hold the source lock during completion", "release(self->lock);\n            using Fn",
     "/* source lock incorrectly held */\n            using Fn"),
]


if __name__ == "__main__":
    from pathlib import Path
    from liftcheck.runner import Checker, Options

    for name, old, new in MUTATIONS:
        checker = Checker(Path(__file__), Options(seed=1, trials=200, patches=((old, new),)))
        rc = checker.run()
        assert rc == 1, ("expected behavioral FAIL, not BUILD/SPEC/UNSUPPORTED", name, rc)
        print(f"CAUGHT {name}", flush=True)
    print(f"PASS xma_source_render: {len(MUTATIONS)} mutations caught")
